import {
  createContext,
  PropsWithChildren,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
} from 'react';

import { BffService } from 'services';

type Kpi = 'pos' | 'power';

type GlobalDataFlag = {
  kpi: Kpi;
  hasGlobalData: boolean;
};

type GlobalDataFlagsMap = Partial<Record<Kpi, boolean>>;

interface GlobalDataAvailabilityContextType {
  isLoading: boolean;
  hasGlobalData: (kpi: Kpi) => boolean;
  shouldShowGlobalBanner: (kpi: Kpi) => boolean;
}

const GlobalDataAvailabilityContext = createContext<
  GlobalDataAvailabilityContextType | undefined
>(undefined);

export const GlobalDataAvailabilityProvider = ({
  children,
}: PropsWithChildren) => {
  const [flags, setFlags] = useState<GlobalDataFlagsMap>({});
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    BffService.getInstance()
      .getData({ endpoint: '/presets/show-global-data', params: {} })
      .then((response) => {
        if (!response || response.hasError) return;

        const data: GlobalDataFlag[] = response.data?.data ?? [];

        const map = data.reduce<GlobalDataFlagsMap>(
          (acc, { kpi, hasGlobalData }) => {
            acc[kpi] = hasGlobalData;
            return acc;
          },
          {},
        );

        setFlags(map);
      })
      .finally(() => setIsLoading(false));
  }, []);

  const hasGlobalData = useCallback(
    (kpi: Kpi): boolean => flags[kpi] ?? true,
    [flags],
  );

  const shouldShowGlobalBanner = useCallback(
    (kpi: Kpi): boolean => !hasGlobalData(kpi),
    [hasGlobalData],
  );

  const value = useMemo(
    () => ({
      isLoading,
      hasGlobalData,
      shouldShowGlobalBanner,
    }),
    [isLoading, hasGlobalData, shouldShowGlobalBanner],
  );

  return (
    <GlobalDataAvailabilityContext.Provider value={value}>
      {children}
    </GlobalDataAvailabilityContext.Provider>
  );
};

export const useGlobalDataAvailability =
  (): GlobalDataAvailabilityContextType => {
    const context = useContext(GlobalDataAvailabilityContext);
    if (!context) {
      throw new Error(
        'useGlobalDataAvailability should be used inside a GlobalDataAvailabilityProvider',
      );
    }
    return context;
  };
